using System.Web.Script.Serialization;
namespace TVLounge {
internal static class GamingToolsTests {
 public static void Run(){Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("Gaming tools: "+label);};var frames=new FrameTracker();frames.Target(42);frames.Line("Application,ProcessID,SwapChainAddress,MsBetweenPresents");frames.Line("\"game, demo.exe\",42,0x1,16.6667");frames.Line("game.exe,42,0x1,16.6667");frames.Line("other.exe,88,0x1,1");check(frames.Snapshot().Fps.HasValue&&Math.Abs(frames.Snapshot().Fps.Value-60)<.01,"FPS must come from the selected process's actual frame events");frames.Line("game.exe,42,0x2,1");check(frames.Snapshot().Fps.Value<61,"Secondary swap chain must not inflate FPS");frames.Line("game.exe,42,0x1,NaN");frames.Line("game.exe,42,0x1,0");frames.Line("broken row");check(frames.Snapshot().Times.Length==2,"Invalid samples must not affect FPS");frames.Target(99);check(!frames.Snapshot().Fps.HasValue,"Changing process must clear stale readings");frames.Target(42);frames.Line("game.exe,42,0x1,16.6667");frames.Line("game.exe,42,0x1,16.6667");Thread.Sleep(1600);check(!frames.Snapshot().Fps.HasValue,"Stopped rendering must show unavailable, not stale FPS");
 check(!ControllerBatteries.IsGameUsage(12,1)&&!ControllerBatteries.IsGameUsage(0xff00,1)&&ControllerBatteries.IsGameUsage(1,5),"Dongle media/vendor interfaces must not appear as duplicate controllers");var realFrames=new FrameTracker();realFrames.Target(1564);realFrames.Line("Application,ProcessID,SwapChainAddress,Runtime,SyncInterval,PresentFlags,Dropped,TimeInSeconds,msInPresentAPI,msBetweenPresents,AllowsTearing,PresentMode");realFrames.Line("dwm.exe,1564,0x000002408E0B7CA0,DXGI,1,2,0,0.6063985,0.2336,16.6083,0,Hardware: Legacy Flip");realFrames.Line("dwm.exe,1564,0x000002408E0B7CA0,DXGI,1,2,0,0.6397535,0.2179,33.355,0,Hardware: Legacy Flip");check(realFrames.Snapshot().Fps.HasValue&&Math.Abs(realFrames.Snapshot().Fps.Value-1000/((16.6083+33.355)/2))<.001,"Bundled PresentMon actual v1 column casing must parse");check(WindowsControllerBattery.Percentage(500,1000)==50&&WindowsControllerBattery.Percentage(null,1000)==-1&&WindowsControllerBattery.Percentage(0,0)==-1&&WindowsControllerBattery.Percentage(1100,1000)==-1,"Windows battery capacities must be validated");check(!WindowsControllerBattery.Unambiguous(2,1)&&!WindowsControllerBattery.Unambiguous(1,2),"Identical controllers must not inherit each other's battery report");var winBattery=new BatteryReading{State=2};check(WindowsControllerBattery.Apply(winBattery,Windows.System.Power.BatteryStatus.Discharging,180,1000)&&winBattery.Low&&winBattery.Percent==18&&winBattery.Category==-1,"Windows percentage must override the inaccurate wired classification");check(!WindowsControllerBattery.Apply(winBattery,Windows.System.Power.BatteryStatus.NotPresent,1000,1000),"Absent batteries must not become full charge");check(WindowsControllerBattery.Apply(winBattery,Windows.System.Power.BatteryStatus.Charging,180,1000)&&!winBattery.Low&&winBattery.Value.Contains("Charging"),"Windows charging status must suppress low alerts");check(WindowsControllerBattery.Apply(winBattery,Windows.System.Power.BatteryStatus.Idle,500,1000)&&winBattery.Value=="50%","Idle at partial capacity must not claim fully charged");var battery=new BatteryReading{Id="controller",State=0,Percent=0};check(!battery.Low&&battery.Value=="Battery unavailable","Unknown must not become a low-battery alert");battery.State=2;check(!battery.Low&&battery.Value.Contains("wired"),"Wired reports must not imply an empty battery");battery.State=1;battery.Category=1;battery.Percent=-1;check(battery.Value=="Low"&&battery.Low,"Xbox charge category must not become an exact percentage");var alerts=new BatteryAlertPolicy();var now=DateTime.UtcNow;check(alerts.Check(battery,now),"Low battery needs one alert");check(!alerts.Check(battery,now.AddMinutes(1)),"Low alert must not repeat on each poll");battery.Category=2;alerts.Check(battery,now.AddMinutes(2));battery.Category=1;check(!alerts.Check(battery,now.AddMinutes(3)),"Charge flapping must not spam");battery.Category=2;alerts.Check(battery,now.AddMinutes(11));battery.Category=1;check(alerts.Check(battery,now.AddMinutes(12)),"A recharged controller can alert in a later discharge");battery.State=3;check(!battery.Low,"Charging must not warn as discharging");
 check(!GameFocus.SameIdentity(40,100,40,101)&&!GameFocus.SameIdentity(40,100,41,100)&&GameFocus.SameIdentity(40,100,40,100),"Refocus must validate process identity, including PID reuse");check(PerformanceHud.FitScale(4,410,438,1920,1080)*470<=1080,"High DPI and large font settings must scale the whole HUD to fit");foreach(var screen in new[]{new Rectangle(-3840,0,3840,2160),new Rectangle(0,0,640,480)})for(int corner=0;corner<4;corner++)check(screen.Contains(PerformanceHud.Placement(screen,corner,1500,1200,64)),"Overlay must fit negative-coordinate and small monitors");
 var s=new Settings{PerformanceEnabled=true,PerformanceShortcut=true,PerformanceMask=0x8020,QuickMenu=true};bool rejected=false;try{OptionalPolicy.Validate(s);}catch(InvalidOperationException){rejected=true;}check(rejected,"Overlay shortcuts must reject quick-menu conflicts");s.PerformanceShortcut=false;s.ReturnGameEnabled=true;s.ReturnGameShortcut=true;s.ReturnGameMask=s.MenuMask;rejected=false;try{OptionalPolicy.Validate(s);}catch(InvalidOperationException){rejected=true;}check(rejected,"Return shortcut must reject quick-menu conflicts");var clone=new JavaScriptSerializer().Deserialize<Settings>(new JavaScriptSerializer().Serialize(new Settings{BatteryMonitoring=true,PerformanceEnabled=true,PerformanceLevel=4,ReturnGameEnabled=true}));check(clone.BatteryMonitoring&&clone.PerformanceLevel==4&&clone.ReturnGameEnabled,"New preferences must survive storage");using(var capture=new PerformanceCapture(new FrameTracker())){capture.EnablePermission(false).GetAwaiter().GetResult();Thread.Sleep(750);check(!capture.Status.StartsWith("FPS unavailable:"),"Capture helper must connect without elevating the whole app");capture.Pause();capture.Start();Thread.Sleep(200);}File.WriteAllText(Storage.PathOf("gaming-tools-tests.txt"),"PASS: frame event parsing, swap-chain isolation, stale FPS, unknown batteries, alert rearming/cooldown, reused process identity, physical overlay bounds, shortcut conflicts, settings persistence.");}
 public static int Probe(){try{Application.EnableVisualStyles();using(var batteries=new ControllerBatteries())using(var telemetry=new HardwareTelemetry()){var controllers=batteries.Read();telemetry.Read();Thread.Sleep(1200);controllers=batteries.Read();var value=telemetry.Read();File.WriteAllText(Storage.PathOf("gaming-tools-probe.json"),new JavaScriptSerializer().Serialize(new{Controllers=controllers.Select(r=>new{r.Name,r.Id,r.Path,r.Kind,r.Connected,r.State,r.Percent,r.Category,r.Value,r.Source}),ControllerError=batteries.Error,XInput=Enumerable.Range(0,4).Select(i=>ControllerInput.Describe((uint)i)).ToArray(),Hardware=value}));using(var hud=new PerformanceHud()){hud.Frames=new FrameSnapshot{Fps=119.9,Times=Enumerable.Range(0,120).Select(i=>8.3+Math.Sin(i*.2)*2).ToArray()};hud.Hardware=value;hud.Battery=controllers.Count==0?"No controller connected":string.Join(" · ",controllers.Select(r=>r.Value));hud.CaptureStatus="Preview";hud.AppName="Performance preview";var foreground=GameFocus.GetForegroundWindow();hud.Configure(new Settings{PerformanceLevel=4,PerformanceOpacity=100,PerformanceScale=200},Screen.PrimaryScreen.DeviceName);if(!hud.NativeStylesCorrect||GameFocus.GetForegroundWindow()!=foreground)throw new Exception("HUD must remain click-through, non-activating and layered at 100% opacity.");for(int level=1;level<=4;level++){hud.Configure(new Settings{PerformanceLevel=level,PerformanceCorner=1},Screen.PrimaryScreen.DeviceName);using(var b=new Bitmap(hud.Width,hud.Height)){hud.DrawToBitmap(b,hud.ClientRectangle);b.Save(Storage.PathOf("performance-level-"+level+".png"));}}hud.Close();}using(var menu=new QuickMenuWindow(new Devices(),Screen.PrimaryScreen.DeviceName,()=>System.Threading.Tasks.Task.FromResult(0),true,true,null,()=>4,l=>{},()=>"GameSir G7 Pro: Battery unavailable\r\nXbox Wireless: Medium",()=>{},()=>true,()=>true)){menu.Show();Application.DoEvents();using(var b=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(b,menu.ClientRectangle);b.Save(Storage.PathOf("gaming-tools-menu.png"));}menu.Close();}}return 0;}catch(Exception e){File.WriteAllText(Storage.PathOf("gaming-tools-probe-error.txt"),e.ToString());return 1;}}
}
